import{t as e}from"./buildPage-DWQZYYcs.js";var t=e({slug:`electrical-estimate`,heroTitle:`Build electrical estimates in minutes`,heroSubtitle:`Perplexity Computer analyzes your uploaded plans, sizes material and labor, and drafts a detailed electrical estimate automatically.`,hasInputUrl:!1,hasInputFile:!0,inputFileCta:`Upload your electrical plans`,inputFileAccept:`.pdf,.doc,.docx,.csv,.xlsx,.xls,.png,.jpg,.jpeg`,inputFilePrefill:`I've uploaded electrical plans, panel schedules, or takeoff notes. Build a complete electrical estimate. (1) Extract fixtures, panels, feeders, branch circuits, conduit runs, devices, controls, and installation constraints from the uploaded files. (2) Estimate materials, prefabrication needs, labor hours, equipment, and subcontractor work where needed. (3) Build pricing options with assumptions, alternates, and margin. (4) Highlight exclusions, field-verification items, and code-sensitive details that should be confirmed before sending. (5) Deliver a detailed electrical estimate with line-item pricing, scope summary, and next steps that is ready for the client.`,heroOverlaySteps:[`Extracting fixtures, panels, conduit runs, and install constraints from your files`,`Sizing materials, labor, equipment, and subcontractor work`,`Building pricing options with assumptions, alternates, and margin`,`Client-ready electrical estimate with scope summary, ready to send`],generatingSteps:[`Reading the uploaded plans, panel schedules, and takeoff notes`,`Designing an agent to organize material counts and labor assumptions`,`Configuring estimate logic for alternates, exclusions, and margin`,`Preparing a detailed electrical estimate with line items and next steps`],featureSectionTitle:`From plans to field-ready estimate`,featureCardTitles:[`Connects to your estimating workflow`,`Estimates built around real install scope`],featureCardDescriptions:[`Computer breaks your project into tasks, spins up specialized agents, and matches each one to the AI model that does it best.`,`Docs, sheets, takeoffs, and internal review workflows stay connected so estimating and revisions move faster.`,`Material counts. Labor assumptions. Alternates. Exclusions. Computer gives your team an electrical estimate draft that is ready for client review.`],capabilitySectionTitle:`Your estimator, on autopilot`,capabilitySectionSubtitle:`Upload the plans, get back an electrical estimate built around the real install scope.`,capabilityCards:[{title:`Plan Analysis`,description:`Computer can extract panels, feeders, branch circuits, conduit runs, devices, and control scope from electrical plans and schedules.`},{title:`Materials & Labor Planning`,description:`Computer can size wire, conduit, gear, equipment, and labor hours so the estimate reflects the actual project instead of a generic template.`},{title:`Pricing Options`,description:`Computer can build pricing with assumptions, alternates, exclusions, and margin so your estimate is clear and easier to approve.`},{title:`Connect Your Tools`,description:`Computer can organize estimate drafts across docs, sheets, and internal workflows so review and handoff are easy for your team.`},{title:`Knows Your Standards`,description:`Computer can remember your preferred vendors, labor assumptions, and estimate structure across sessions so every quote stays consistent.`},{title:`Revision Support`,description:`Computer can update the estimate when drawings shift, alternates change, or field conditions alter the original scope.`}]});export{t as default};
